#!/usr/bin/env node
/**
 * validate-contrast.mjs — Gate de Contraste WCAG 2.2 AA
 *
 * Valida programaticamente que as combinações oficiais de cor do projeto
 * respeitam os limiares de contraste WCAG 2.2 AA:
 *   - Texto normal  : 4.5:1 (critério 1.4.3)
 *   - Texto grande  : 3:1   (critério 1.4.3)
 *   - Componentes UI: 3:1   (critério 1.4.11)
 *
 * Lê as cores permitidas de dock-ds.config.json e valida combinações
 * obrigatórias declaradas em contrast.pairs (ou combinações padrão).
 *
 * Uso:
 *   node node_modules/@dock-tech/shared-copilot-front-lib/scripts/validate-contrast.mjs
 *   npm run validate:contrast
 *
 * Exit code 0 = todas as combinações passam WCAG AA
 * Exit code 1 = violação encontrada
 */

import { readFileSync, existsSync } from 'fs';
import { join } from 'path';

const CWD = process.cwd();

// ── Helpers WCAG ──────────────────────────────────────────────────────────────

/**
 * Converte hex para sRGB (0..1)
 */
function hexToRGB(hex) {
  const clean = hex.replace('#', '');
  const full = clean.length === 3
    ? clean.split('').map((c) => c + c).join('')
    : clean.slice(0, 6);

  return {
    r: parseInt(full.slice(0, 2), 16) / 255,
    g: parseInt(full.slice(2, 4), 16) / 255,
    b: parseInt(full.slice(4, 6), 16) / 255,
  };
}

/**
 * Converte canal sRGB para luminância linear (WCAG formula)
 */
function linearize(c) {
  return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

/**
 * Luminância relativa de uma cor hex (WCAG 2.2 — 1.4.3)
 */
function relativeLuminance(hex) {
  const { r, g, b } = hexToRGB(hex);
  return 0.2126 * linearize(r) + 0.7152 * linearize(g) + 0.0722 * linearize(b);
}

/**
 * Razão de contraste entre dois hex. Sempre ≥ 1.
 */
function contrastRatio(hex1, hex2) {
  const l1 = relativeLuminance(hex1);
  const l2 = relativeLuminance(hex2);
  const lighter = Math.max(l1, l2);
  const darker  = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

// ── Config ────────────────────────────────────────────────────────────────────

function loadConfig() {
  const configPath = join(CWD, 'dock-ds.config.json');
  if (!existsSync(configPath)) {
    console.error('❌ dock-ds.config.json não encontrado.');
    console.error('   Execute npm run validate:contrast apenas em projetos com dock-ds.config.json.');
    process.exit(1);
  }
  return JSON.parse(readFileSync(configPath, 'utf-8'));
}

const config = loadConfig();

// ── Resolução de tokens CSS (var(--x) → #hex) ──────────────────────────────────
// Fecha o gap C.4 do PRD: antes só validávamos hex literais; agora resolvemos
// os tokens semânticos que o código real usa, e por TEMA (light/dark separados).

function themeArg() {
  const i = process.argv.indexOf('--theme');
  return i >= 0 && process.argv[i + 1] ? process.argv[i + 1].toLowerCase() : 'light';
}
const THEME = themeArg();

function loadTokenMap() {
  // Caminhos configuráveis; defaults cobrem as convenções do DS.
  const files = config.tokens?.cssFiles || [
    'tokens.css',
    'src/styles/tokens/primitive.css',
    'src/styles/tokens/semantic.css',
    'src/design-system/tokens.css',
  ];
  const base = {}; // :root / light
  const dark = {}; // [data-theme="dark"]

  const blockRx = /([^{}]+)\{([^{}]+)\}/g;
  const declRx = /(--[\w-]+)\s*:\s*([^;]+);/g;

  for (const rel of files) {
    const full = join(CWD, rel);
    if (!existsSync(full)) continue;
    const css = readFileSync(full, 'utf-8');
    let block;
    while ((block = blockRx.exec(css)) !== null) {
      const selector = block[1].toLowerCase();
      const body = block[2];
      const target = /\bdark\b/.test(selector) ? dark : base;
      let decl;
      while ((decl = declRx.exec(body)) !== null) {
        target[decl[1].trim()] = decl[2].trim();
      }
    }
  }
  return { base, dark };
}

const TOKEN_MAP = loadTokenMap();

// Resolve um valor (#hex | var(--x) | --x) para #hex, seguindo aliases.
function resolveColor(input, depth = 0) {
  if (!input || depth > 12) return null;
  let v = String(input).trim();

  if (v.startsWith('#')) return v;

  // var(--x) ou var(--x, fallback)
  const varMatch = v.match(/^var\(\s*(--[\w-]+)\s*(?:,\s*([^)]+))?\)$/);
  let tokenName = null;
  let fallback = null;
  if (varMatch) {
    tokenName = varMatch[1];
    fallback = varMatch[2] ? varMatch[2].trim() : null;
  } else if (v.startsWith('--')) {
    tokenName = v;
  }

  if (tokenName) {
    const scope = THEME === 'dark' ? { ...TOKEN_MAP.base, ...TOKEN_MAP.dark } : TOKEN_MAP.base;
    const resolved = scope[tokenName];
    if (resolved != null) return resolveColor(resolved, depth + 1);
    if (fallback != null) return resolveColor(fallback, depth + 1);
    return null; // token não encontrado
  }

  // valores não suportados (rgb/hsl/named) — devolve como veio se for hex-like
  return /^#?[0-9a-fA-F]{3,8}$/.test(v) ? (v.startsWith('#') ? v : '#' + v) : null;
}

// Combinações obrigatórias declaradas em config.contrast.pairs
// Formato: [{ foreground, background, level, label }]
//   level: "AA-text" (4.5:1) | "AA-large" (3:1) | "AA-ui" (3:1)
const DECLARED_PAIRS = config.contrast?.pairs || [];

// Cores permitidas do projeto (para gerar combinações padrão se não houver pairs declarados)
const ALLOWED_COLORS = config.tokens?.colors || [];

// Combinações padrão com branco e preto quando não há pairs declarados
const WHITE = '#ffffff';
const BLACK = '#000000';

// Limiares por nível WCAG
const THRESHOLDS = {
  'AA-text':  4.5,
  'AA-large': 3.0,
  'AA-ui':    3.0,
};

// ── Validação ─────────────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;
const violations = [];

function check(fg, bg, level, label) {
  const ratio = contrastRatio(fg, bg);
  const threshold = THRESHOLDS[level] || 4.5;
  const ok = ratio >= threshold;

  if (ok) {
    passed++;
    if (process.env.CONTRAST_VERBOSE) {
      console.log(`  ✓ ${label} — ${ratio.toFixed(2)}:1 (mín ${threshold}:1)`);
    }
  } else {
    failed++;
    violations.push({ label, fg, bg, ratio: ratio.toFixed(2), required: threshold, level });
    console.log(`  ✗ ${label}`);
    console.log(`      ${fg} sobre ${bg} → ${ratio.toFixed(2)}:1 (exige ${threshold}:1 — WCAG ${level})`);
  }
}

console.log('═'.repeat(60));
console.log('  🎨 Dock Contrast Gate — WCAG 2.2 AA');
console.log('═'.repeat(60));

if (DECLARED_PAIRS.length > 0) {
  // ── Modo declarativo: valida pares registrados em config ─────────────────
  console.log(`\n📋 Pares declarados em dock-ds.config.json: ${DECLARED_PAIRS.length} (tema: ${THEME})`);

  for (const pair of DECLARED_PAIRS) {
    const level = pair.level || 'AA-text';
    const label = pair.label || `${pair.foreground} / ${pair.background}`;
    const fg = resolveColor(pair.foreground);
    const bg = resolveColor(pair.background);

    if (!fg || !bg) {
      failed++;
      const missing = [!fg && pair.foreground, !bg && pair.background].filter(Boolean).join(', ');
      violations.push({ label, fg: pair.foreground, bg: pair.background, ratio: 'n/a', required: THRESHOLDS[level] || 4.5, level });
      console.log(`  ✗ ${label} — token não resolvido (${missing}). Verifique tokens.cssFiles em dock-ds.config.json.`);
      continue;
    }
    check(fg, bg, level, label);
  }
} else if (ALLOWED_COLORS.length > 0) {
  // ── Modo automático: valida cada cor contra branco e preto ───────────────
  console.log(`\n🔍 Validando ${ALLOWED_COLORS.length} cores contra branco/preto (modo automático)`);
  console.log('   Para controle explícito, adicione "contrast.pairs" ao dock-ds.config.json\n');

  for (const color of ALLOWED_COLORS) {
    if (!color.startsWith('#')) continue;

    const ratioOnWhite = contrastRatio(color, WHITE);
    const ratioOnBlack = contrastRatio(color, BLACK);

    // Cor passa se funciona como texto AA sobre branco OU sobre preto
    // (o projeto usa ela em pelo menos uma combinação segura)
    const textSafe = ratioOnWhite >= 4.5 || ratioOnBlack >= 4.5;
    const uiSafe   = ratioOnWhite >= 3.0 || ratioOnBlack >= 3.0;

    if (!uiSafe) {
      failed++;
      violations.push({
        label: `${color} (sem combinação AA segura)`,
        fg: color,
        bg: `branco(${ratioOnWhite.toFixed(2)}) / preto(${ratioOnBlack.toFixed(2)})`,
        ratio: Math.max(ratioOnWhite, ratioOnBlack).toFixed(2),
        required: 3.0,
        level: 'AA-ui',
      });
      console.log(`  ✗ ${color} — sem combinação AA (branco: ${ratioOnWhite.toFixed(2)}:1 / preto: ${ratioOnBlack.toFixed(2)}:1)`);
    } else if (!textSafe) {
      // Aviso: cor OK para UI mas não para texto
      console.log(`  ⚠️  ${color} — OK para UI (${Math.max(ratioOnWhite, ratioOnBlack).toFixed(2)}:1) mas NÃO para texto corrido (< 4.5:1)`);
      passed++;
    } else {
      passed++;
      if (process.env.CONTRAST_VERBOSE) {
        console.log(`  ✓ ${color} — texto AA OK (branco: ${ratioOnWhite.toFixed(2)} / preto: ${ratioOnBlack.toFixed(2)})`);
      }
    }
  }
} else {
  console.log('\n⚠️  Nenhuma cor configurada em dock-ds.config.json → tokens.colors.');
  console.log('   Adicione as cores do projeto e rode novamente.');
  process.exit(0);
}

// ── Relatório Final ───────────────────────────────────────────────────────────

console.log('\n' + '─'.repeat(60));
console.log(`  Resultado: ${passed} passou, ${failed} falhou (${passed + failed} total)`);
console.log('─'.repeat(60));

if (violations.length > 0) {
  console.log('\n❌ Violações WCAG encontradas:');
  violations.forEach((v, i) => {
    console.log(`\n  ${i + 1}. ${v.label}`);
    console.log(`     Ratio: ${v.ratio}:1  (exige ${v.required}:1 — WCAG ${v.level})`);
    console.log(`     Foreground: ${v.fg}  Background: ${v.bg}`);
  });

  console.log('\n  Como corrigir:');
  console.log('  → Ajuste o valor da cor ou a combinação declarada em dock-ds.config.json');
  console.log('  → Referência: https://webaim.org/resources/contrastchecker/\n');

  process.exit(1);
}

console.log('\n✅ Todas as combinações passam WCAG 2.2 AA!\n');
process.exit(0);
